"""All 23 pages are part of the main presentation, ordered by the Pre6 assignment."""
from questions import QUESTIONS


def page(title, speaker, seconds, section, goal, speech, cue, refs):
    return dict(title=title,speaker=speaker,seconds=seconds,section=section,goal=goal,
                speech=speech,cue=cue,refs=refs)


